_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "497b7277-85d1-56ce-e6ef-914d4cb64cd3", "sort_order": 0, "title": "Hawa Mahal", "description": "Palace of Winds'' eternalloveliness.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "4f14c485-0e4b-1271-13b8-f4aa4e31951c", "sort_order": 1, "title": "City Palace", "description": "Royal residence with historical meaning.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "0ed27542-633c-55dc-9708-1c89cb38c0f1", "sort_order": 2, "title": "Observatory / Jantar Mantar", "description": "Astronomical wonders of ancient times.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "c4a1a190-e7f1-b62f-4abc-c79addcc4ae7", "sort_order": 3, "title": "Jal Mahal", "description": "Lake palace in calm waters.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "a4844806-9598-8e27-b1e9-c756c6979f49", "sort_order": 4, "title": "Amer Fort", "description": "Majestic fort atop picturesque hills.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "faff783d-db25-156c-7b62-686e4111a886", "sort_order": 5, "title": "Nahargarh Fort & Palace", "description": "Overseeing Jaipur with regal attraction.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "ce804636-0e29-1e98-eb01-b9f7d504e96